/// What one MCP row's arm returns.
type McpVerbRowResult = Result<
    (
        Value,
        crate::mcp::McpPageSource,
        McpCarrierPolicy,
        Option<u64>,
    ),
    McpGatewayError,
>;
/// One MCP row's arm, boxed by its own function (FIX 19837).
type McpVerbRowFuture<'a> =
    std::pin::Pin<Box<dyn std::future::Future<Output = McpVerbRowResult> + Send + 'a>>;
/// [`execute_agent_verb_row_on`]'s arguments, moved whole into the one row's arm.
struct McpVerbRow<'a> {
    server: &'a Arc<SyncServer>,
    tool: &'a str,
    input: Value,
    actor: &'a McpCallContext,
    memory: oneiron::Memory<'a>,
    surface: McpRowSurface,
    served: &'a mut McpServed,
    board_hooks: &'a mut Option<super::board_setup::McpBoardHooks>,
    pre_hooked_fold: Option<oneiron::code_run::actions::PreHookedFold>,
}
#[inline(never)]
fn boxed_mcp_verb_row_vault_commitments_create<'a>(row: McpVerbRow<'a>) -> McpVerbRowFuture<'a> {
    Box::pin(mcp_verb_row_vault_commitments_create(row))
}
async fn mcp_verb_row_vault_commitments_create(row: McpVerbRow<'_>) -> McpVerbRowResult {
    let McpVerbRow {
        server,
        tool,
        input,
        actor,
        memory,
        surface,
        served,
        board_hooks,
        pre_hooked_fold,
    } = row;
    let _ = (
        &server,
        &tool,
        &input,
        &actor,
        &memory,
        &surface,
        &served,
        &board_hooks,
        &pre_hooked_fold,
    );
    let invalid = || {
        McpGatewayError::new(
            -32602,
            "tool_args_invalid",
            "invalid typed agent-verb argument",
        )
    };
    let auth = actor.auth.as_ref().ok_or_else(invalid)?;
    oneiron::task_verb::sdk::validate_input("vault.commitments.create", &input)
        .map_err(mcp_facade_error)?;
    let input: oneiron::memory::commitment_doors::CommitmentCreateRequest =
        serde_json::from_value(input).map_err(|_| invalid())?;
    let (output, listed) = Box::pin(crate::api::facade::host_doors::vault_commitments_create(
        server, auth, input,
    ))
    .await;
    // Derived from the rows its reads listed: unknown when its path lists none (FIX 5988).
    served.listed(crate::api::facade::host_doors::support::ListedRows::rows(
        listed,
    ));
    let output = output.map_err(mcp_facade_error)?;
    let source = crate::mcp::McpPageSource::complete(1);
    mcp_agent_verb_output(output, source)
}
