#[inline(never)]
fn boxed_mcp_verb_row_describe<'a>(row: McpVerbRow<'a>) -> McpVerbRowFuture<'a> {
    Box::pin(mcp_verb_row_describe(row))
}
async fn mcp_verb_row_describe(row: McpVerbRow<'_>) -> McpVerbRowResult {
    let McpVerbRow {
        server,
        tool,
        input,
        actor,
        memory,
        surface,
        served,
        board_hooks,
        pre_hooked_fold,
    } = row;
    let _ = (
        &server,
        &tool,
        &input,
        &actor,
        &memory,
        &surface,
        &served,
        &board_hooks,
        &pre_hooked_fold,
    );
    let invalid = || {
        McpGatewayError::new(
            -32602,
            "tool_args_invalid",
            "invalid typed agent-verb argument",
        )
    };
    oneiron::task_verb::sdk::validate_input("describe", &input).map_err(mcp_facade_error)?;
    if input.get("self").and_then(Value::as_bool) == Some(true) {
        let auth = actor.auth.as_ref().ok_or_else(invalid)?;
        let (value, listed) = Box::pin(crate::api::context_board::describe_self_for_auth(
            server, auth, &input,
        ))
        .await
        .map_err(|_| invalid())?;
        // Derived from the rows its card lists, the roster it read among them.
        served.extend(listed);
        let output: oneiron::task_verb::TaskDescription =
            serde_json::from_value(value).map_err(|_| invalid())?;
        let (value, source) = mcp_describe_result(output)?;
        return Ok((value, source, McpCarrierPolicy::Drain, None));
    }
    let input: oneiron::task_verb::sdk::DescribeRequest =
        serde_json::from_value(input).map_err(|_| invalid())?;
    if let Some(key) = input.key.clone() {
        let frame_epoch = input.frame_epoch;
        return Box::pin(execute_mcp_board_verb(
            server,
            actor,
            served,
            board_hooks,
            |context| {
                oneiron::board_verb::dispatch_board_verb(
                    context,
                    oneiron::board_verb::BoardVerbCall::Expand { key, frame_epoch },
                )
            },
        ))
        .await;
    }
    if input.task_ref.is_none()
        && input.handle.is_none()
        && input.after.is_none()
        && !input.self_target
        && !input.vault
    {
        // The section is narrowed to this credential before its
        // render cap, so its counts are the credential's rows alone.
        let rows = memory.describe_rows().map_err(mcp_facade_error)?;
        let (value, source) = mcp_tasks_section(server, actor, rows, served)?;
        return Ok((value, source, McpCarrierPolicy::Drain, None));
    }
    served.extend(oneiron::task_verb::sdk::describe_named_rows(&input));
    let output = oneiron::task_verb::sdk::describe(&memory, input).map_err(mcp_facade_error)?;
    let (value, source) = mcp_describe_result(output)?;
    Ok((value, source, McpCarrierPolicy::Drain, None))
}
