#[inline(never)]
fn boxed_mcp_verb_row_vault_export<'a>(row: McpVerbRow<'a>) -> McpVerbRowFuture<'a> {
    Box::pin(mcp_verb_row_vault_export(row))
}
async fn mcp_verb_row_vault_export(row: McpVerbRow<'_>) -> McpVerbRowResult {
    let McpVerbRow {
        server,
        tool,
        input,
        actor,
        memory,
        surface,
        served,
        board_hooks,
        pre_hooked_fold,
    } = row;
    let _ = (
        &server,
        &tool,
        &input,
        &actor,
        &memory,
        &surface,
        &served,
        &board_hooks,
        &pre_hooked_fold,
    );
    let invalid = || {
        McpGatewayError::new(
            -32602,
            "tool_args_invalid",
            "invalid typed agent-verb argument",
        )
    };
    let auth = actor.auth.as_ref().ok_or_else(invalid)?;
    if !auth.is_owner_grade() {
        return Err(McpGatewayError::new(
            -32020,
            "forbidden",
            "full-vault export requires owner authority",
        ));
    }
    oneiron::task_verb::sdk::validate_input("vault.export", &input).map_err(mcp_facade_error)?;
    let input: oneiron::memory::ExportOptions =
        serde_json::from_value(input).map_err(|_| invalid())?;
    // A host credential resolves first (FIX 2222): a hosted operator root gets the typed refusal, and a self-hosted root or the explicit dev mode exports as the owner it acts as.
    let action = crate::api::host_action::host_action_of(server.vault(), auth)
        .transpose()
        .map_err(|error| mcp_engine_error("host action failed", error))?;
    // The person path lists through its surface; the host paths beside their archive. A slip keeps its own path; a host action with no slip (the dev mode) takes the host-action export.
    // Each arm records the owner act with where he spoke from: an MCP row carries no request headers (FIX 4625, 4626).
    let surface = crate::api::facade::owner_binding::act_surface(auth);
    // A transfer is kept on the server, as on REST, and read through vault.export.transfer.read (FIX 11176).
    if input.delivery.unwrap_or_default() == oneiron::memory::ExportDelivery::Transfer {
        let (transfer, listed) = crate::api::facade::mcp_export_transfer(
            server,
            auth,
            surface,
            &actor.destination(),
            &input,
            action,
        )
        .map_err(mcp_facade_error)?;
        served.extend(listed);
        return mcp_agent_verb_output(transfer, crate::mcp::McpPageSource::complete(1));
    }
    let output = match (auth.verified_slip(), action) {
        (Some(proof), _) if proof.claims().holder_ref == "host" => server
            .vault
            .export_with_verified_host_owner_listing(&input, proof, surface, actor.destination())
            .map(|(output, listed)| {
                served.extend(listed);
                output
            }),
        (Some(proof), _) => memory.export_with_verified_owner(&input, proof, surface),
        (None, Some(action)) => server
            .vault
            .export_with_host_action_listing(&input, &action, surface, actor.destination())
            .map(|(output, listed)| {
                served.extend(listed);
                output
            }),
        // A managed vault's attested owner carries no slip: the request's own owner proof, which the export revalidates in its snapshot, as the facade takes it (FIX 5202).
        (None, None) if auth.managed_owner().is_some() => {
            let owner = crate::api::owner_routes::owner(auth, server).map_err(|_| {
                McpGatewayError::new(
                    -32020,
                    "forbidden",
                    "full-vault export requires verified owner authority",
                )
            })?;
            server
                .vault
                .export_with_authenticated_owner_listing(
                    &input,
                    &owner,
                    surface,
                    actor.destination(),
                )
                .map(|(output, listed)| {
                    served.extend(listed);
                    output
                })
        }
        (None, None) => {
            return Err(McpGatewayError::new(
                -32020,
                "forbidden",
                "full-vault export requires verified owner authority",
            ));
        }
    }
    .map_err(mcp_facade_error)?;
    let source = crate::mcp::McpPageSource::complete(1);
    mcp_agent_verb_output(output, source)
}
