async fn mcp_verb_row_vault_projects_confirm(row: McpVerbRow<'_>) -> McpVerbRowResult {
    let McpVerbRow {
        server,
        tool,
        input,
        actor,
        memory,
        surface,
        served,
        board_hooks,
        pre_hooked_fold,
    } = row;
    let _ = (
        &server,
        &tool,
        &input,
        &actor,
        &memory,
        &surface,
        &served,
        &board_hooks,
        &pre_hooked_fold,
    );
    let invalid = || {
        McpGatewayError::new(
            -32602,
            "tool_args_invalid",
            "invalid typed agent-verb argument",
        )
    };
    let auth = actor.auth.as_ref().ok_or_else(invalid)?;
    oneiron::task_verb::sdk::validate_input("vault.projects.confirm", &input)
        .map_err(mcp_facade_error)?;
    let input: oneiron::workspace_roster::ProjectCardConfirmRequest =
        serde_json::from_value(input).map_err(|_| invalid())?;
    let (output, listed) = Box::pin(crate::api::facade::host_doors::vault_projects_confirm(
        server,
        auth,
        actor
            .off_record_session
            .as_deref()
            .map(oneiron::EntityId::from_hex)
            .transpose()
            .map_err(|_| invalid())?,
        input,
    ))
    .await;
    // Derived from the rows its reads listed: unknown when its path lists none (FIX 5988).
    served.listed(crate::api::facade::host_doors::support::ListedRows::rows(
        listed,
    ));
    let output = output.map_err(mcp_facade_error)?;
    let source = crate::mcp::McpPageSource::complete(1);
    mcp_agent_verb_output(output, source)
}
